CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,display_name text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_members(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')),PRIMARY KEY(workspace_id,user_id));
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),canonical_name text NOT NULL,normalized_name text UNIQUE NOT NULL);
CREATE TABLE boards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,company_id uuid REFERENCES companies(id),provider text NOT NULL,board_key text,board_url text,config jsonb NOT NULL DEFAULT '{}'::jsonb,status text NOT NULL DEFAULT 'untested',last_attempt_at timestamptz,last_success_at timestamptz);
CREATE TABLE jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,company_id uuid REFERENCES companies(id),board_id uuid REFERENCES boards(id) ON DELETE SET NULL,canonical_url text NOT NULL,title text NOT NULL,description text,location_text text,locations jsonb NOT NULL DEFAULT '[]',country text,city text,workplace_type text,employment_type text,department text,salary jsonb,posted_at timestamptz,first_seen_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),active boolean NOT NULL DEFAULT true,content_hash text,source_provider text,UNIQUE(workspace_id,canonical_url));
CREATE INDEX jobs_active_idx ON jobs(workspace_id,active,last_seen_at DESC);
CREATE TABLE job_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,observed_at timestamptz NOT NULL DEFAULT now(),snapshot jsonb NOT NULL);
CREATE TABLE job_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,event_type text NOT NULL,event_at timestamptz NOT NULL DEFAULT now(),payload jsonb NOT NULL DEFAULT '{}');
CREATE TABLE saved_jobs(user_id uuid REFERENCES users(id) ON DELETE CASCADE,job_id uuid REFERENCES jobs(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,job_id));
CREATE TABLE focus_companies(workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,company_id uuid REFERENCES companies(id) ON DELETE CASCADE,PRIMARY KEY(workspace_id,company_id));
CREATE TABLE refresh_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,status text NOT NULL,started_at timestamptz,finished_at timestamptz,summary jsonb NOT NULL DEFAULT '{}');
CREATE TABLE board_fetch_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),refresh_run_id uuid REFERENCES refresh_runs(id) ON DELETE CASCADE,board_id uuid REFERENCES boards(id) ON DELETE SET NULL,status text NOT NULL,jobs_count integer NOT NULL DEFAULT 0,error_code text,error_message text,duration_ms integer,fetched_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,rule jsonb NOT NULL,enabled boolean NOT NULL DEFAULT true);
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),alert_id uuid REFERENCES alerts(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,event jsonb NOT NULL,delivery_status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());